// Search the Material icon catalogue for the Visual Builder's icon picker.
//
// The catalogue (data/mui-icons.json, ~2,000 icons / ~550KB, regenerated by
// scripts/gen-mui-icons.mjs) is read on the server and never sent whole: the
// picker asks for a page of matches and gets back only those icons' path
// data. Shipping the file to the browser would mean half a megabyte before
// anyone has typed anything, and sending it to the public site would defeat
// the point of storing only the icons a page actually uses.
import { NextRequest, NextResponse } from "next/server";
import { MUI_VIEW_BOX, searchMuiIcons } from "@/lib/muiIcons";

const MAX_LIMIT = 120;

export async function GET(req: NextRequest) {
  // Admin-only, enforced by middleware.ts: every path except login/signup,
  // /api/auth, /api/internal and /api/webhooks needs a session cookie, so an
  // anonymous request never reaches this handler.

  const url = new URL(req.url);
  const q = (url.searchParams.get("q") || "").trim().toLowerCase();
  const limit = Math.min(MAX_LIMIT, Math.max(1, Number(url.searchParams.get("limit")) || 60));

  const { total, icons } = searchMuiIcons(q, limit);
  return NextResponse.json({ total, viewBox: MUI_VIEW_BOX, icons });
}
